<?php
// JSON endpoint: securely add or remove the current member's favorite and return the updated count.
require_once __DIR__.'/helpers.php';require_login();header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['error'=>'POST required']);exit;}
$sent=$_SERVER['HTTP_X_CSRF_TOKEN']??'';if(!hash_equals(csrf_token(),$sent)){http_response_code(419);echo json_encode(['error'=>'Session expired']);exit;}$data=json_decode(file_get_contents('php://input'),true);$id=filter_var($data['recipe_id']??null,FILTER_VALIDATE_INT);if(!$id){http_response_code(422);echo json_encode(['error'=>'Invalid recipe']);exit;}$q=$pdo->prepare('SELECT id FROM recipes WHERE id=?');$q->execute([$id]);if(!$q->fetch()){http_response_code(404);echo json_encode(['error'=>'Recipe not found']);exit;}$uid=(int)$_SESSION['user']['id'];$q=$pdo->prepare('SELECT 1 FROM favorites WHERE user_id=? AND recipe_id=?');$q->execute([$uid,$id]);$saved=(bool)$q->fetchColumn();if($saved){$q=$pdo->prepare('DELETE FROM favorites WHERE user_id=? AND recipe_id=?');$q->execute([$uid,$id]);$saved=false;}else{$q=$pdo->prepare('INSERT IGNORE INTO favorites(user_id,recipe_id) VALUES(?,?)');$q->execute([$uid,$id]);$saved=true;}$q=$pdo->prepare('SELECT COUNT(*) FROM favorites WHERE recipe_id=?');$q->execute([$id]);echo json_encode(['saved'=>$saved,'count'=>(int)$q->fetchColumn()]);
